package dev.arabicgames.tv;
import android.content.*;import android.media.tv.*;import android.view.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadow.api.Shadow;import org.robolectric.util.ReflectionHelpers;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,shadows={TvHdmiResumeTest.Inputs.class,TvHdmiResumeTest.Info.class,TvHdmiResumeTest.Video.class})
public class LegacyHdmiActivityTest {
 @Before public void reset(){TvHdmiResumeTest.Inputs.list.clear();TvHdmiResumeTest.Video.tunes=0;TvHdmiResumeTest.Video.resets=0;RuntimeEnvironment.getApplication().getSharedPreferences("MainActivity",0).edit().clear().commit();}
 private org.robolectric.android.controller.ActivityController<LegacyHdmiActivity> controller(){var c=Robolectric.buildActivity(LegacyHdmiActivity.class);org.robolectric.shadows.ShadowContextImpl base=Shadow.extract(c.get().getBaseContext());base.setSystemService(Context.TV_INPUT_SERVICE,Shadow.newInstanceOf(TvInputManager.class));c.setup().visible();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();return c;}
 private static Button find(View v,String text){if(v instanceof Button&&text.equals(((Button)v).getText().toString()))return(Button)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){Button b=find(((ViewGroup)v).getChildAt(i),text);if(b!=null)return b;}return null;}
 @Test public void reopeningControlsDoesNotTuneSavedHdmi(){RuntimeEnvironment.getApplication().getSharedPreferences("MainActivity",0).edit().putString("hdmi","tcl-HDMI-2").commit();TvHdmiResumeTest.Inputs.list.add(Shadow.newInstanceOf(TvInputInfo.class));try(var c=controller()){assertEquals(0,TvHdmiResumeTest.Video.tunes);assertEquals("tcl-HDMI-2",c.get().getPreferences(0).getString("hdmi",""));assertNotNull(find(c.get().getWindow().getDecorView(),"عرض اللعبة عبر HDMI"));}}
 @Test public void legacyManualTuneKeepsSessionAcrossPauseStop(){TvHdmiResumeTest.Inputs.list.add(Shadow.newInstanceOf(TvInputInfo.class));try(var c=controller()){find(c.get().getWindow().getDecorView(),"عرض اللعبة عبر HDMI").performClick();assertEquals(1,TvHdmiResumeTest.Video.tunes);c.pause().stop();assertEquals(0,TvHdmiResumeTest.Video.resets);c.start().resume();assertEquals(1,TvHdmiResumeTest.Video.tunes);}}
 @Test public void legacyPlaybackFocusIsNotBlockedByRoot(){try(var c=controller()){TvView tv=ReflectionHelpers.getField(c.get(),"tv");assertNotEquals(ViewGroup.FOCUS_BLOCK_DESCENDANTS,tv.getDescendantFocusability());find(c.get().getWindow().getDecorView(),"عودة للعب").performClick();assertFalse(((View)tv.getParent()).isFocusableInTouchMode());assertTrue(c.get().getPreferences(0).contains("receiverId"));}}
 @Test public void launcherUsesModernScreen(){Intent i=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LEANBACK_LAUNCHER).setPackage("dev.arabicgames.tv");var r=RuntimeEnvironment.getApplication().getPackageManager().resolveActivity(i,0);assertNotNull(r);assertEquals(MainActivity.class.getName(),r.activityInfo.name);}
}
